insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-01',1,'갈등관리','나와 의견이 다른 사람과 싸우지 않고, 대화로 문제를 풀어 모두가 만족하는 결과를 만든 경험',array['Q.친구들이나 동료들과 의견 충돌이 있었을 때, 내가 나서서 대화로 오해를 풀고 분위기를 좋게 만든 적이 있나요?','Q.서로 조금씩 양보해서 모두가 윈윈(WIN-WIN) 했던 에피소드가 있나요?'],array['conflict-mediation','listening-empathy'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 61626, "paragraph": 146}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-02',2,'계획력','무작정 일을 시작하지 않고, 미리 꼼꼼하게 순서를 정하고 혹시 모를 문제까지 대비해 본 경험',array['Q.일의 중요도에 따라 순서를 정해 계획을 세워본 적이 있나요?','Q.계획대로 안 될 때를 대비해서 ''플랜 B(위기 대처 계획)''까지 미리 짜둔 적이 있나요?'],array['goal-persistence','problem-response'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 62559, "paragraph": 150}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-03',3,'국민지향성','상대방의 입장에서 먼저 생각하고, 상대가 원하거나 불편해하는 것을 미리 눈치채서 해결해 준 경험',array['Q.아르바이트나 봉사활동을 할 때, 손님이나 사람들의 불만을 미리 파악하고 나서서 도와줘 칭찬을 받은 적이 있나요?'],array['service-action','listening-empathy'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 63450, "paragraph": 154}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-04',4,'기획력','조직의 큰 목표를 이루기 위해 상황을 분석하고, 구체적인 아이디어나 실행 계획을 짜본 경험',array['Q. 동아리나 팀 프로젝트에서 우리가 나아갈 방향을 잡고, ''이렇게 해보면 어떨까?'' 하고 구체적인 기획안을 내본 적이 있나요?'],array['initiative','shared-goal'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 64219, "paragraph": 157}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-05',5,'도전정신','실패할 수도 있지만, 더 나은 결과를 위해 과감하게 안 해본 일이나 새로운 방식을 시도해 본 경험',array['Q. 남들이 안 하려고 하는 어려운 일에 자원하거나, ''원래 하던 방식''을 버리고 과감히 새로운 방식을 시도해 본 적이 있나요?'],array['initiative','goal-persistence'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 65737, "paragraph": 163}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-06',6,'리더십','팀원들에게 목표를 명확히 알려주고, 어려운 상황에서도 팀원들을 다독여 결국 목표를 이뤄낸 경험',array['Q. 조장이나 리더를 맡아서, 하기 싫어하는 팀원들을 설득하고 도와가며 프로젝트를 성공적으로 끝낸 적이 있나요?'],array['leadership-action'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 66604, "paragraph": 167}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-07',7,'문제해결력','예상치 못한 문제가 터졌을 때 당황하지 않고, 진짜 원인을 찾아내서 정확한 해결책을 낸 경험',array['Q. 어려운 문제에 부딪혔을 때, 감정적으로 대처하지 않고 객관적인 자료나 논리를 바탕으로 문제를 척척 해결한 적이 있나요?'],array['problem-response'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 67361, "paragraph": 170}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-08',8,'분석력','겉으로 보이는 것만 믿지 않고, 자료나 상황을 깊이 파고들어 장단점을 비교하고 진짜 의미를 찾아낸 경험',array['Q. 여러 가지 선택지가 있을 때, 통계나 자료를 꼼꼼히 비교·분석해서 가장 좋은 답을 찾아낸 적이 있나요?'],array['problem-response','judgement-priority'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 68220, "paragraph": 174}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-09',9,'설득력','나와 의견이 다른 사람을 타당한 이유와 자료를 들어 내 편으로 만들거나 동의를 얻어낸 경험',array['Q. 반대하는 사람을 말로만 우기지 않고, 정확한 자료나 예시를 보여주며 설득해서 내 의견을 통과시킨 적이 있나요?'],array['conflict-mediation'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 68983, "paragraph": 177}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-10',10,'목표달성능력','누가 시키지 않아도 내 스스로 목표를 높게 잡고, 중간에 포기하지 않고 끝까지 해내서 좋은 결과를 낸 경험',array['Q. 힘든 장애물이 있었는데도 대충 타협하지 않고, 내 한계를 뛰어넘어 기대 이상의 성과를 이뤄낸 적이 있나요?'],array['goal-persistence'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 70407, "paragraph": 183}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-11',11,'수리감각 및 수익성','돈, 시간, 인원 등 숫자로 된 자료를 정확하게 다루고, 자원을 낭비 없이 효율적으로 써본 경험',array['Q. 동아리 총무나 행사 기획을 하면서, 정해진 예산을 꼼꼼히 계산하고 아껴서 가장 효율적으로 써본 적이 있나요?'],array['judgement-priority','duty-reliability'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 71188, "paragraph": 186}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-12',12,'의사결정 판단능력','정보가 부족하거나 시간이 없는 다급한 상황에서도, 타이밍을 놓치지 않고 빠르고 정확하게 결정을 내린 경험',array['Q. 빨리 결정을 내려야 하는 긴급한 상황에서, 망설이지 않고 소신껏 판단해서 일을 잘 처리한 적이 있나요?'],array['judgement-priority','problem-response'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 72001, "paragraph": 189}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-13',13,'자기계발','남들의 쓴소리나 내 단점을 인정하고, 나를 더 발전시키기 위해 스스로 계획을 세워 꾸준히 노력한 경험',array['Q. 주변의 피드백을 듣고 내 부족한 점을 고치기 위해 스스로 공부하거나 훈련한 적이 있나요?'],array['feedback-change','preparation-learning'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 72818, "paragraph": 192}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-14',14,'적응력','갑자기 환경이 바뀌거나 처음 해보는 낯선 일이라도 당황하지 않고 금방 룰을 익혀 적응해 낸 경험',array['Q. 새로운 모임, 낯선 아르바이트 장소, 혹은 규칙이 갑자기 바뀐 상황에서 불평하지 않고 빠르게 융화된 적이 있나요?'],array['organization-adaptation'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 73569, "paragraph": 195}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-15',15,'전략적 사고력','일이 복잡하게 꼬여 있을 때 ''무엇이 제일 먼저이고 중요한지'' 파악해서 우선순위대로 똑똑하게 처리한 경험',array['Q. 할 일이 쏟아질 때, 중요도와 시급성을 따져서 순서를 정하고 꼬인 상황을 깔끔하게 정리해 본 적이 있나요?'],array['judgement-priority','problem-response'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 74340, "paragraph": 198}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-16',16,'정보수집능력','어떤 일을 할 때 필요한 알짜배기 정보를 스스로 찾아내고, 그걸 보기 좋게 정리해서 업무에 써먹은 경험',array['Q. 남들은 잘 모르는 고급 정보나 꼭 필요한 자료를 내가 직접 발품 팔아 찾아내고 활용해서 문제를 해결한 적이 있나요?','Q. 인터넷이나 책에 흩어져 있는 방대한 자료들을 수집한 뒤, 다른 사람들이 한눈에 이해하기 쉽게 핵심만 요약하거나 보기 좋게 정리해 본 적이 있나요?'],array['preparation-learning','problem-response'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 75784, "paragraph": 204}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-17',17,'정직·윤리의식','내가 조금 손해를 보거나 불편하더라도 양심과 원칙을 지켰거나, 남들의 잘못된 행동을 바로잡아 본 경험',array['Q. 아무도 보는 사람이 없거나 융통성을 핑계로 쉽게 갈 수 있었는데도, 끝까지 규정과 원칙을 지킨 적이 있나요?','Q. 친한 친구나 동료가 규칙을 어기거나 편법을 쓰려고 할 때, 그냥 넘기지 않고 용기 내어 올바른 행동을 하도록 설득해 본 적이 있나요?'],array['honesty','fairness-integrity'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 76861, "paragraph": 208}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-18',18,'주도적·적극성','시키는 일만 하는 게 아니라, 내가 스스로 할 일을 찾아서 내 일처럼 책임감을 가지고 앞장서서 한 경험',array['Q. 내 담당이 아니거나 주어진 과제가 끝났는데도, 팀을 위해 내가 알아서 일을 더 찾아서 해본 적이 있나요?','Q. 누가 지시하기 전에 미리 ''앞으로 이런 문제가 생길 것 같은데?''라고 예상하고, 선제적으로 대비책을 마련해 본 적이 있나요?'],array['initiative'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 77916, "paragraph": 212}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-19',19,'창의력','남들이 다 하는 뻔한 방식 말고, 나만의 색다른 아이디어나 새로운 방법으로 문제를 통쾌하게 풀어본 경험',array['Q. 전혀 상관없어 보이는 두 가지를 연결하거나, 아무도 생각 못한 새로운 방식으로 답답한 상황을 뚫어본 적이 있나요?','Q. 다들 ''이건 원래 안 되는 거야''라고 포기했던 문제에서, 작은 발상의 전환을 통해 틈새 해결책을 찾아내 성공시킨 적이 있나요?'],array['initiative','problem-response'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 78961, "paragraph": 216}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-20',20,'책임감','아무리 힘들어도 내가 맡은 일은 남 탓이나 핑계를 대지 않고 끝까지 완벽하게 마무리한 경험',array['Q. 실수가 있었을 때 숨기거나 남에게 떠넘기지 않고, 내 잘못을 인정한 뒤 밤을 새워서라도 끝까지 책임을 진 적이 있나요?','Q. 내 역할이 너무 벅차고 포기하고 싶은 순간이 있었지만, 나를 믿고 맡겨준 사람들을 실망시키지 않기 위해 끈기 있게 완수해 낸 적이 있나요?'],array['duty-reliability','honesty'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 80008, "paragraph": 220}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-21',21,'체계적인 사고','뒤죽박죽 얽혀있는 복잡한 일에서 규칙을 찾아내, 누구나 알아보기 쉽게 깔끔한 패턴으로 정리해 본 경험',array['Q. 복잡한 업무나 중구난방인 자료들을 나만의 기준으로 분류해서, 효율적으로 처리할 수 있는 새로운 룰을 만든 적이 있나요?','Q. 해야 할 일이 산더미처럼 쌓여 있을 때, 무작정 시작하지 않고 전체 과정을 여러 단계로 쪼개어 우선순위대로 차근차근 해결해 본 적이 있나요?'],array['problem-response','judgement-priority'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 81728, "paragraph": 227}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-22',22,'추진력','중간에 반대가 있거나 생각지 못한 벽에 부딪혀도, 포기하지 않고 처음에 계획한 목표를 향해 끝까지 밀고 나간 경험',array['Q. 남들이 다 안 될 거라고 반대하거나 힘든 장애물이 나타났을 때도, 뚝심 있게 내 계획을 밀어붙여 성과를 낸 적이 있나요?','Q. 다들 생각만 하고 미루던 일이나 아무도 나서지 않는 일에, 내가 앞장서서 총대를 메고 빠르게 실행에 옮겨본 적이 있나요?'],array['initiative','goal-persistence'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 82803, "paragraph": 231}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-23',23,'치밀성','아주 작은 실수나 오타 하나도 놓치지 않으려고, 여러 번 꼼꼼하게 다시 확인해서 사고를 미리 막은 경험',array['Q. 사소해 보이는 부분까지 이중, 삼중으로 크로스 체크해서, 나중에 일어날 뻔한 큰 실수를 미리 잡아낸 적이 있나요?','Q. 다른 사람들은 ''이 정도면 됐다''고 대충 넘어간 일에서 미세한 오류를 발견하고, 끝까지 완벽하게 다듬어 본 적이 있나요?'],array['duty-reliability','problem-response'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 83862, "paragraph": 235}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-24',24,'커뮤니케이션 능력','내 생각을 상대방의 눈높이에 맞춰 오해 없이 정확하게 전달하고, 상대방의 말도 잘 들어준 경험',array['Q. 어려운 내용을 상대방이 이해하기 게 비유나 표정, 바디랭귀지 등을 써서 찰떡같이 설명해 본 적이 있나요?“','Q. 말수가 적거나 불만이 있는 상대방의 진짜 속마음을 끝까지 들어주고(경청), 그 사람이 원하는 바를 정확히 파악해 오해를 푼 적이 있나요?'],array['listening-empathy','conflict-mediation'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 84901, "paragraph": 239}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-25',25,'팀워크','내가 조금 돋보이지 않더라도 팀의 성공을 위해 양보하거나, 뒤처지는 팀원을 먼저 나서서 도와준 경험',array['Q. 내 고집을 버리고 팀의 결정을 따르거나, 도움이 필요한 동료에게 먼저 손을 내밀어 팀 전체의 분위기를 올린 적이 있나요?','Q. 조별 과제나 단체 활동에서 겉도는 팀원이 있을 때, 그 사람이 소외되지 않고 작은 역할이라도 맡아 참여할 수 있도록 이끌어준 적이 있나요?'],array['shared-goal','mutual-support','followership'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 85988, "paragraph": 243}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-26',26,'혁신 사고력','원래 다 이렇게 해''라는 관행에 의문을 품고, 더 편하고 효율적인 새로운 방식을 찾아내서 고쳐본 경험',array['Q. 늘 하던 비효율적인 방식을 보고 ''이거 이렇게 바꾸면 어떨까?'' 제안해서 사람들의 일 처리를 훨씬 편하게 만들어준 적이 있나요?','Q. 남들이 다 하는 뻔한 방식 대신, 전혀 다른 분야의 아이디어나 새로운 도구를 가져와서 문제를 신선하게 해결해 본 적이 있나요?'],array['initiative','problem-response'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 87051, "paragraph": 247}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-27',27,'성인지감수성','성별에 따른 차별, 편견, 불평등을 인식하고, 이를 개선하려는 태도 및 타인의 경계를 존중하며 평등하게 소통하는 역량',array['Q. 일상생활이나 모임에서 무의식적인 성별 고정관념이나 편견 섞인 말을 들었을 때, 이를 조심하거나 부드럽게 바로잡아 본 적이 있나요?','Q. 다양한 성별의 팀원들과 함께 일할 때, 서로를 동등하게 존중하며 수평적인 분위기 속에서 좋은 결과를 낸 적이 있나요?','Q. 누군가가 차별을 느낄 수 있는 상황을 미리 캐치하고, 상대방을 배려해 조심스럽게 행동한 적이 있나요?'],array['respect-inclusion','rights-protection'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 88781, "paragraph": 254}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-28',28,'예의 품행','타인을 존중하고 배려하는 태도를 바탕으로, 상황과 장소에 맞는 적절한 언행과 규범을 준수하여 원만한 대인관계를 형성하는 역량',array['Q. 나이 차이가 많이 나거나 생각이 완전히 다른 사람을 대할 때, 끝까지 예의를 갖춰서 긍정적인 관계를 만든 적이 있나요?','Q. 상대방이 무례하게 굴거나 화를 내는 상황에서도, 같이 흥분하지 않고 차분하고 정중하게 대처해 본 적이 있나요?','Q. 다들 귀찮아하는 기본적인 조직 규칙이나 공공장소 에티켓을 나부터 솔선수범해서 지켜, 주변의 신뢰를 얻은 적이 있나요?'],array['respect-inclusion','emotion-regulation'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 90134, "paragraph": 259}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-29',29,'성실성','자신에게 주어진 역할과 책임을 다하기 위해 일관되고 꾸준하게 노력하며, 작은 일이라도 정성을 다해 완수하는 태도',array['Q. 남들이 알아주지 않는 귀찮은 일이나 단순 반복 업무라도, 꼼수 부리지 않고 끝까지 묵묵히 해낸 적이 있나요?','Q. 오래 걸리는 목표를 세운 뒤, 중간에 포기하고 싶은 유혹을 이겨내고 매일 꾸준히 노력해서 작은 성과라도 이뤄낸 적이 있나요?','Q. 정말 피곤하거나 힘든 상황에서도 지각이나 결석 한 번 없이 내 할 일을 다해서 칭찬을 받은 적이 있나요?'],array['duty-reliability','goal-persistence'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 91491, "paragraph": 264}'::jsonb ) on conflict(id) do nothing;
insert into public.ip_life_competencies(id,position,title,definition,questions,element_ids,source) values ('life-30',30,'사회적 가치판단','개인의 이익보다 공공의 이익과 공동체의 발전을 우선시하며, 사회적 약자를 배려하고 올바른 시민 의식을 실천하는 역량',array['Q. 돈이나 대가가 주어지지 않는데도, 순수하게 다른 사람이나 우리 동네를 위해 봉사하고 뿌듯함을 느낀 적이 있나요?','Q. 내가 조금 손해를 보거나 불편해지더라도, 여러 사람을 위해 양심적으로 행동하고 원칙을 지킨 적이 있나요?','Q. 길을 가다 곤란에 처한 사람이나 사회적 약자를 보고 그냥 지나치지 않고, 먼저 다가가 도움의 손길을 건넨 적이 있나요?'],array['public-mission','service-action','fairness-integrity'],'{"filename": "[론박스터디] 인생그래프 DB 만들기 서식.hwp", "sha256": "23df681784071547ccdda9a8e7ae2d1eef01368039aac6a76132e3af38e189b9", "stream": "BodyText/Section0", "offset": 92784, "paragraph": 269}'::jsonb ) on conflict(id) do nothing;
